29	const splitTaskListItemChildren = (children: ReactNode) => {
30	  let checkbox: ReactNode;
31	  const content: ReactNode[] = [];
32	
33	  Children.toArray(children).forEach((child) => {
34	    if (!checkbox && isCheckboxInput(child)) {
35	      checkbox = child;
36	      return;
37	    }
38	
39	    if (!checkbox && isParagraphElement(child)) {
40	      const paragraphChildren: ReactNode[] = [];
41	
42	      Children.toArray(child.props.children).forEach((paragraphChild) => {
43	        if (!checkbox && isCheckboxInput(paragraphChild)) {
