50	      if (checkbox) {
51	        if (paragraphChildren.length > 0) {
52	          content.push(cloneElement(child, undefined, ...paragraphChildren));
53	        }
54	        return;
55	      }
56	    }
57	
58	    content.push(child);
59	  });
60	
61	  return { checkbox, content };
