10	  node?: {
11	    tagName?: string;
12	    properties?: {
13	      type?: unknown;
14	    };
15	  };
16	  type?: string;
17	}
18	
19	const isCheckboxInput = (child: ReactNode): child is ReactElement<TaskListChildProps> => {
20	  return (
21	    isValidElement<TaskListChildProps>(child) && (child.props.type === "checkbox" || child.props.node?.properties?.type === "checkbox")
22	  );
23	};
24	
25	const isParagraphElement = (child: ReactNode): child is ReactElement<TaskListChildProps> => {
26	  return isValidElement<TaskListChildProps>(child) && (child.type === "p" || child.props.node?.tagName === "p");
27	};
28	
29	const splitTaskListItemChildren = (children: ReactNode) => {
30	  let checkbox: ReactNode;
31	  const content: ReactNode[] = [];
32	
33	  Children.toArray(children).forEach((child) => {
34	    if (!checkbox && isCheckboxInput(child)) {
35	      checkbox = child;
36	      return;
37	    }
38	
39	    if (!checkbox && isParagraphElement(child)) {
40	      const paragraphChildren: ReactNode[] = [];
41	
42	      Children.toArray(child.props.children).forEach((paragraphChild) => {
43	        if (!checkbox && isCheckboxInput(paragraphChild)) {
44	          checkbox = paragraphChild;
45	          return;
46	        }
47	        paragraphChildren.push(paragraphChild);
48	      });
49	
50	      if (checkbox) {
51	        if (paragraphChildren.length > 0) {
52	          content.push(cloneElement(child, undefined, ...paragraphChildren));
53	        }
54	        return;
55	      }
56	    }
57	
58	    content.push(child);
59	  });
60	
61	  return { checkbox, content };
62	};
63	
64	interface ListProps extends React.HTMLAttributes<HTMLUListElement | HTMLOListElement>, ReactMarkdownProps {
65	  ordered?: boolean;
66	  children: React.ReactNode;
67	}
68	
69	/**
70	 * List component for both regular and task lists (GFM)
71	 * Detects task lists via the "contains-task-list" class added by remark-gfm
72	 */
73	export const List = ({ ordered, children, className, node: _node, ...domProps }: ListProps) => {
74	  const Component = ordered ? "ol" : "ul";
75	  const isTaskList = className?.includes(TASK_LIST_CLASS);
76	  // Task list indentation is handled by task item grid columns; regular lists
77	  // use the shared token (padding + list style).
78	  const listClass = isTaskList ? "my-0 mb-2 list-outside list-none" : ordered ? markdownStyles.orderedList : markdownStyles.bulletList;
79	
80	  return (
81	    <Component className={cn(listClass, className)} {...domProps}>
82	      {children}
83	    </Component>
84	  );
85	};
86	
87	interface ListItemProps extends React.LiHTMLAttributes<HTMLLIElement>, ReactMarkdownProps {
88	  children: React.ReactNode;
89	}
90	
91	/**
92	 * List item component for both regular and task list items
93	 * Detects task items via the "task-list-item" class added by remark-gfm
94	 */
95	export const ListItem = ({ children, className, node: _node, ...domProps }: ListItemProps) => {
96	  const isTaskListItem = className?.includes(TASK_LIST_ITEM_CLASS);
97	
98	  if (isTaskListItem) {
99	    const { checkbox, content } = splitTaskListItemChildren(children);
100	
101	    return (
102	      <li className={cn(markdownStyles.taskListItem, className)} {...domProps}>
103	        <NestedMarkdownRenderContext>
104	          {checkbox}
105	          <div className={markdownStyles.taskItemContent}>{content}</div>
106	        </NestedMarkdownRenderContext>
107	      </li>
108	    );
109	  }
110	
111	  return (
112	    <li className={cn(markdownStyles.listItem, className)} {...domProps}>
113	      <NestedMarkdownRenderContext>{children}</NestedMarkdownRenderContext>
114	    </li>
